#!/bin/bash
# Script seguro usando base64

cd ~/Right100

# Decodificar e escrever PhotoVideoActivity.kt
echo "" | base64 -d > app/src/main/kotlin/com/goodwy/gallery/activities/PhotoVideoActivity.kt

# Decodificar e escrever ViewPagerActivity.kt
echo "" | base64 -d > app/src/main/kotlin/com/goodwy/gallery/activities/ViewPagerActivity.kt

# Decodificar e escrever MyPagerAdapter.kt
echo "" | base64 -d > app/src/main/kotlin/com/goodwy/gallery/adapters/MyPagerAdapter.kt

# Remover refreshMenuItems() duplicado do ViewPagerFragment
sed -i '/fun refreshMenuItems()/d' app/src/main/kotlin/com/goodwy/gallery/fragments/ViewPagerFragment.kt
# Adicionar refreshMenuItems() na interface (se não existir)
sed -i 's/fun isFullScreen(): Boolean/fun isFullScreen(): Boolean

        fun refreshMenuItems() {}/' app/src/main/kotlin/com/goodwy/gallery/fragments/ViewPagerFragment.kt

# Corrigir PhotoFragment
sed -i 's/?.refreshMenuItems()/?\.invalidateOptionsMenu()/g' app/src/main/kotlin/com/goodwy/gallery/fragments/PhotoFragment.kt

# VideoFragment: renomear handleTouchHoldEventLocal de volta para handleTouchHoldEvent
# e implementar o método
sed -i 's/handleTouchHoldEventLocal(event)/handleTouchHoldEvent(event)/g' app/src/main/kotlin/com/goodwy/gallery/fragments/VideoFragment.kt

# VideoFragment: adicionar override em handleEvent
sed -i 's/^    fun handleEvent(event: MotionEvent)/    override fun handleEvent(event: MotionEvent)/' app/src/main/kotlin/com/goodwy/gallery/fragments/VideoFragment.kt

# Commit e push
git add -A
git commit -m "Fix: Corrige todos os erros de compilacao v2"
git push origin master

echo "✅ CORREÇÕES ENVIADAS"
